<?php
 namespace QQWorld\Braintree\Test\Constraint; use QQWorld\Checkout\Test\Page\CheckoutOnepage; use QQWorld\Mtf\Constraint\AbstractConstraint; class AssertCreditCardJsValidationMessagesArePresent extends AbstractConstraint { public function processAssert(CheckoutOnepage $checkoutOnepage, array $expectedErrorMessages) { $errorMessages = $checkoutOnepage->getBraintreeBlock()->getVisibleMessages($expectedErrorMessages); foreach (array_keys($errorMessages) as $field) { \PHPUnit_Framework_Assert::assertEquals( $expectedErrorMessages[$field], $errorMessages[$field], "Wrong js validation error message is displayed for field: $field." ); } } public function toString() { return 'Js validation error messages are correct for required fields.'; } } 